const response = $json.choices[0].message.content;

const competitorAnalysis = JSON.parse(response);

return [
  {
    json: {
      analysis_request_id: $('Fetch AI Analysis').first().json.analysis_request_id,

      direct_competitors: competitorAnalysis.direct_competitors,
      indirect_competitors: competitorAnalysis.indirect_competitors,
      competitor_strengths: competitorAnalysis.competitor_strengths,
      competitor_weaknesses: competitorAnalysis.competitor_weaknesses,
      market_positioning: competitorAnalysis.market_positioning,
      competitive_landscape_summary: competitorAnalysis.competitive_landscape_summary,
      analysis_status: competitorAnalysis.analysis_status,
      confidence_score: competitorAnalysis.confidence_score,
      updated_at: competitorAnalysis.updated_at
    }
  }
];
